import{z as l,x as p,o as A,c as B,q as s,j as o,D as e,d as E,s as i,S as n,b as r}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"备份与 PITR","description":"","frontmatter":{"title":"备份与 PITR","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/backup-pitr.md","filePath":"cs/backup-pitr.md","lastUpdated":1791063341000}'),d={name:"cs/backup-pitr.md"};function T(c,a,D,m,P,u){const t=p("Mermaid");return A(),B("div",null,[a[2]||(a[2]=s('<h1 id="备份与-pitr" tabindex="-1">备份与 PITR <a class="header-anchor" href="#备份与-pitr" aria-label="Permalink to &quot;备份与 PITR&quot;">​</a></h1><div class="epigraph"><p>备份是过去某检查点的数据文件像；PITR 再把 WAL 前滚到指定时间。基线与日志链缺一不可。</p><footer>—— 据 Gray and Reuter 备份；PostgreSQL PITR；物理备份实践</footer></div><p><a href="/cs/rto-recovery">上一课</a>谈崩溃重启。本课谈<strong>介质失败与误删除</strong>：ARIES 救不了删掉的文件或逻辑错误（drop table）。备份+时间点恢复（PITR）用基线副本+连续 WAL 归档。逻辑复制下一课是另一条传送变化的路。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>物理备份：拷数据文件（常模糊一致+WAL 补齐）或快照。逻辑备份：dump SQL，慢、粒度表，可跨版本。PITR：从基线前滚 WAL 到时间 T 或某 LSN/事务。缺口是<strong>归档完整性</strong>：WAL 缺口则只能回到缺口前。误操作恢复要停在错误前，RPO 取决于归档粒度。</p><p>备份本身要测恢复，否则只是占用对象存储。与 TDE：备份密文，恢复要密钥。</p><p><span class="marginnote">Postgres <code>recovery_target_time</code>。热备份 vs 冷备份。本课不背某云快照 API。</span></p><p><span class="marginnote">术语翻译：PITR（Point-In-Time Recovery，时间点恢复）就是「把数据库拨回指定时刻」：先铺好上周的底片（基线副本），再一格格播放之后的操作日志（WAL），放到想停的那一帧按暂停。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>全量+增量（变化页）+ WAL。保留窗口：能 PITR 多远。校验：备份后 checksum、定期试恢复到临时实例。应用：恢复后可能要处理序列、复制槽、连接密码。</p><p>与组提交：归档的是已持久日志。异步提交未进归档的会丢，与 D 等级一致。</p>',11)),(A(),o(n,null,{default:e(()=>[i(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20BASE%5B%22%E5%9F%BA%E7%BA%BF%E6%95%B0%E6%8D%AE%E5%83%8F%22%5D%20--%3E%20ROLL%5B%22%E5%BA%94%E7%94%A8%E5%BD%92%E6%A1%A3%20WAL%22%5D%0A%20%20ROLL%20--%3E%20T%5B%22%E5%81%9C%E5%9C%A8%E6%97%B6%E9%97%B4%20T%22%5D%0A%20%20GAP%5B%22WAL%20%E7%BC%BA%E5%8F%A3%22%5D%20--%3E%20STOP%5B%22%E5%8F%AA%E8%83%BD%E5%9B%9E%E5%88%B0%E7%BC%BA%E5%8F%A3%E5%89%8D%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[E("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"模糊备份：拷文件时页在变，必须靠同时段 WAL redo 修到一致——与模糊检查点同构。快照若原子则少修。逻辑 dump 无 PITR 细粒度，除非再叠逻辑日志。",-1)),(A(),o(n,null,{default:e(()=>[i(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20T0%5B%22%E5%91%A8%E4%B8%80%3A%20%E5%85%A8%E9%87%8F%E5%9F%BA%E7%BA%BF%22%5D%20--%3E%20T1%5B%22%E6%AF%8F%E5%A4%A9%3A%20%E5%A2%9E%E9%87%8F%E5%8F%98%E5%8C%96%E9%A1%B5%22%5D%0A%20%20T1%20--%3E%20T2%5B%22%E6%8C%81%E7%BB%AD%3A%20WAL%20%E6%8C%89%E6%AE%B5%E5%BD%92%E6%A1%A3%22%5D%0A%20%20T2%20--%3E%20BAD%5B%22%E5%91%A8%E4%B8%89%2014%3A00%3A%20%E8%AF%AF%E5%88%A0%E8%A1%A8%22%5D%0A%20%20BAD%20--%3E%20Q%7B%22%E6%81%A2%E5%A4%8D%E7%9B%AE%E6%A0%87%E8%83%BD%E5%81%9C%E5%9C%A8%E5%93%AA%E4%B8%AA%E6%97%B6%E5%88%BB%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E8%AF%AF%E6%93%8D%E4%BD%9C%E5%89%8D%E4%B8%80%E7%A7%92%22%7C%20R1%5B%22%E5%89%8D%E6%BB%9A%E5%88%B0%2013%3A59%3A59%20%E5%81%9C%E6%AD%A2%22%5D%0A%20%20Q%20--%3E%7C%22%E5%BD%92%E6%A1%A3%E5%9C%A8%2013%3A30%20%E6%96%AD%E4%BA%86%22%7C%20R2%5B%22%E6%9C%80%E8%BF%9C%E5%8F%AA%E8%83%BD%E5%9B%9E%E5%88%B0%2013%3A30%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=s('<p><span class="marginnote">直觉类比：WAL 像记账流水——基线是上月底的存折余额，WAL 是之后每一笔收支；想算任意一天的余额，从月底余额往后累加即可。但缺了一页流水，那一页之后的日子就永远算不回来，这正是「缺口打断链」。</span></p><p>膨胀：未 vacuum 的堆会把死元组拷进备份，体积与恢复时间都差。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 CDC 解析。也不把备份当只读副本（延迟与用途不同）。Jepsen 后课测的是运行时一致，不是备份链。</p><p>后课默认：介质与误操作靠备份+PITR；崩溃靠 ARIES。逻辑复制与 CDC：把行变化流给下游，不是整库前滚。</p><p>没有演练的 PITR 目标时间是愿望。</p><p><span class="marginnote">常见误区：「备份任务显示成功＝能恢复」——没做过试恢复的备份只是一堆运气好的文件。缺段、密钥丢失、恢复步骤报错，全都可能直到第一次真恢复那天才爆出来，所以校验的核心动作是定期把它真的恢复到一台临时实例。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>物理基线+WAL 链做 PITR；缺口打断链。</li><li>备份要试恢复；密文备份依赖密钥。</li><li>逻辑复制与 CDC 下一课。</li><li>出处：Gray and Reuter；PostgreSQL PITR。</li></ul>',9))])}const _=l(d,[["render",T]]);export{h as __pageData,_ as default};
